export const meta = {
  name: 'agents-md-workflow-review',
  description: 'Audit AGENTS.md workflow for internal soundness and consistency with the actual repo',
  phases: [
    { title: 'Audit', detail: 'four independent lenses over AGENTS.md' },
    { title: 'Verify', detail: 'adversarially check each lens findings against ground truth' },
    { title: 'Synthesize', detail: 'merge into a ranked report' },
  ],
}

const REPO = '/home/scottdensmore/Developer/scottdensmore/petspotr'

const COMMON = `You are auditing the file ${REPO}/AGENTS.md, which is the single source of truth for the AI-agent development workflow in this Go/GCP repository.

Read the WHOLE file first. Then investigate the actual repository to check claims. Relevant ground truth lives in: .github/workflows/ci.yml, .claude/agents/*.md, .golangci.yml, go.mod, .markdownlint.json, docker-compose.yml, tests/playwright/, e2e/, cmd/, pkg/, infra/opentofu/, deploy/cloudrun/, docs/, README.md, CLAUDE.md, and the git history (git log --oneline -30).

Only report findings you can substantiate with a specific line of AGENTS.md and, where the claim is about the repo, a specific file/command you checked. Do NOT report vague style opinions or "could be clearer" nits. Every finding must name a concrete consequence: what an agent following this document would do wrong, or what a reader would be unable to determine.`

const SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'one-line claim' },
          location: { type: 'string', description: 'AGENTS.md section and/or line numbers' },
          evidence: { type: 'string', description: 'exact quoted text from AGENTS.md plus the repo file/command checked and what it showed' },
          consequence: { type: 'string', description: 'what goes wrong concretely for an agent following this doc' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          fix: { type: 'string', description: 'concrete suggested edit' },
        },
        required: ['title', 'location', 'evidence', 'consequence', 'severity', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          real: { type: 'boolean', description: 'true only if you independently confirmed it' },
          why: { type: 'string', description: 'what you checked and what you found; if refuted, say exactly what the finder got wrong' },
          corrected_severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          corrected_fix: { type: 'string' },
        },
        required: ['title', 'real', 'why', 'corrected_severity', 'corrected_fix'],
      },
    },
  },
  required: ['verdicts'],
}

const LENSES = [
  {
    key: 'ground-truth',
    prompt: `${COMMON}

YOUR LENS: factual drift between AGENTS.md and the repository as it actually exists.

Verify every checkable assertion, including but not limited to:
- The Go toolchain claim "must report go1.26.5" vs what actions/setup-go pins in ci.yml, vs go.mod, vs the locally installed go version (run: go version).
- Every pinned tool version (golangci-lint v2.12.2, markdownlint-cli 0.49.1, OpenTofu 1.12.5) vs ci.yml.
- The markdownlint file list in AGENTS.md vs the hardcoded list in ci.yml, vs the .md files that actually exist (find . -name '*.md' -not -path './node_modules/*' -not -path './.git/*').
- The claim ".golangci.yml uses the v2 config schema".
- CI job names/count ("five jobs", "the first four are required") vs the actual job keys and name: values in ci.yml.
- The repo layout table: do all five cmd/ services exist? do all six pkg/ packages exist (domain, store, pubsub, blob, ollama, scoring)? does docs/ contain exactly DEVELOPMENT.md and MIGRATION_PLAN.md?
- The docker compose command's service names vs docker-compose.yml.
- The Playwright claim that the suite contains both API and browser specs, and that it needs only three services.
- The Ollama model name "gemma4:e2b" vs what the code/compose actually reference.
- Whether .claude/agents/ contains exactly the three registered subagents named.`,
  },
  {
    key: 'workflow-logic',
    prompt: `${COMMON}

YOUR LENS: is the 11-step workflow + gate discipline internally sound and executable as written?

Trace an agent literally executing it end to end. Hunt for: ordering problems, circular or unbounded gate loops, rules that contradict each other across sections (e.g. step 7 vs step 8 vs step 10 rerun rules vs the "Branch protection" rerun rule vs "Rerun only what the change invalidated" vs "Two rounds maximum"), ambiguity about WHICH gate the two-round cap counts, undefined terms, steps with no defined exit condition, and situations the doc leaves undecided (e.g. what to do when ui-review and code-review disagree; whether the two-round cap resets after a rerun triggered by a different gate; what happens when a gate's rerun triggers another gate's rerun).

Also check the interaction between step 5 (file gh issues for out-of-scope work) and the gates: is it clear when a finding is "actionable now" vs "file an issue"? Is the pre-authorization scope clear (gh issue create only, or more)?

Do not report a finding unless a reasonable agent could genuinely act two different ways on it.`,
  },
  {
    key: 'subagent-alignment',
    prompt: `${COMMON}

YOUR LENS: do the registered subagent definitions in ${REPO}/.claude/agents/ match what AGENTS.md says about them?

Read code-review.md, verifier.md, and ui-review.md in full. Compare against AGENTS.md's "Registered subagents" section, "Test execution ownership" table, "Applicability" table, "Verification scope", and "Code Review Rules".

Look for: responsibilities claimed in one place and absent in the other; verification commands or tool versions duplicated in an agent file that could drift from AGENTS.md (AGENTS.md line 8-10 explicitly forbids agent files from carrying project facts, gate applicability, and verification commands — check whether the agent files actually comply); the "focused-support mode" vs "formal gate" distinction being defined in AGENTS.md but not in verifier.md (or vice versa); tool grants in the agent frontmatter that make a documented responsibility impossible (e.g. can ui-review actually drive a browser? can verifier run docker/npm?); the three Code Review Rules being enforceable by code-review.md as written.

Also check .agents/, .codex/, .cursor/, and .entire/ for competing entrypoint files that contradict AGENTS.md's "single source of truth" claim.`,
  },
  {
    key: 'gaps-and-friction',
    prompt: `${COMMON}

YOUR LENS: what is MISSING or practically unworkable, judged against how this repo is actually developed.

Read git log (git log --oneline -40) and inspect 2-3 recent merge commits to see how work actually lands. Check docs/DEVELOPMENT.md and docs/MIGRATION_PLAN.md and README.md for workflow guidance that AGENTS.md omits or contradicts.

Hunt for genuine gaps an agent would hit, such as: no guidance on what to do when the local Go toolchain does not match the pinned version (the doc says check it, but not what to do if it differs); no stated procedure for updating a version pin across AGENTS.md + ci.yml; the doc says "the file list is hardcoded in the workflow; renaming or adding a top-level doc requires updating it in the same commit" — is that actually achievable given branch protection?; nothing about how to handle a failing e2e-playwright-tests job given it is explicitly not a required check; no guidance about the Ollama/gemma dependency during local dev; missing rollback/revert procedure despite step 2 invoking "quick rollback"; no guidance on issue/PR linkage (does a PR close the tracked issue?).

Be ruthless about relevance: a gap only counts if an agent working in THIS repo would plausibly hit it and be blocked or guess wrong. Do not propose adding bureaucracy for its own sake — this doc's brevity is a feature.`,
  },
]

phase('Audit')

const results = await pipeline(
  LENSES,
  (lens) => agent(lens.prompt, { label: `audit:${lens.key}`, phase: 'Audit', schema: SCHEMA }),
  (found, lens) => {
    if (!found || !found.findings || found.findings.length === 0) return { lens: lens.key, verdicts: [] }
    const list = found.findings
      .map((f, i) => `--- FINDING ${i + 1}: ${f.title}
Location: ${f.location}
Evidence claimed: ${f.evidence}
Consequence claimed: ${f.consequence}
Severity claimed: ${f.severity}
Proposed fix: ${f.fix}`)
      .join('\n')
    return agent(
      `You are an adversarial verifier. Another agent audited ${REPO}/AGENTS.md through the "${lens.key}" lens and produced the findings below. Your job is to REFUTE them.

Read AGENTS.md yourself. Independently re-check every factual claim against the actual repository files and commands — do not trust the finder's quoted evidence, re-read the source. Run commands where that settles it (e.g. go version, grep in .github/workflows/ci.yml, ls of directories).

Mark real=false when: the quoted AGENTS.md text is misquoted or taken out of context; the doc actually does address it in another section the finder missed; the repo does not in fact contradict the doc; the "consequence" is speculative rather than something an agent would really do wrong; or the finding is a style preference dressed up as a defect. Default to real=false when you are not sure.

For findings that survive, correct the severity if the finder inflated it, and tighten the proposed fix into a precise, minimal edit to AGENTS.md (quote the replacement text where short).

${list}

Return one verdict per finding, in the same order, using the same titles.`,
      { label: `verify:${lens.key}`, phase: 'Verify', schema: VERDICT_SCHEMA, effort: 'high' },
    ).then((v) => ({ lens: lens.key, findings: found.findings, verdicts: (v && v.verdicts) || [] }))
  },
)

const confirmed = []
for (const r of results.filter(Boolean)) {
  const fs = r.findings || []
  const vs = r.verdicts || []
  vs.forEach((v, i) => {
    if (v.real) {
      const f = fs[i] || {}
      confirmed.push({
        lens: r.lens,
        title: v.title || f.title,
        location: f.location,
        evidence: f.evidence,
        consequence: f.consequence,
        severity: v.corrected_severity || f.severity,
        fix: v.corrected_fix || f.fix,
        verifier_note: v.why,
      })
    }
  })
}

log(`${confirmed.length} findings survived adversarial verification`)

if (confirmed.length === 0) {
  return { confirmed: [], summary: 'No findings survived verification.' }
}

phase('Synthesize')

const synthesis = await agent(
  `You are writing the final report on an audit of ${REPO}/AGENTS.md — the workflow document for AI coding agents in this repo. The user asked simply: "does the workflow make sense?"

Below are the findings that survived adversarial verification. Read AGENTS.md yourself for context before synthesizing.

Produce a report with:
1. A verdict paragraph: does the workflow make sense as a whole? Be direct and fair — say what is genuinely well-designed about it, not just what is broken. This document is unusually rigorous; do not manufacture criticism.
2. Findings merged (dedupe overlaps across lenses) and ranked by severity, each as: a bolded one-line claim, the AGENTS.md location, the concrete consequence, and the precise suggested edit.
3. A short "leave alone" note listing anything that looks like a problem but is deliberate and correct.

Be concise and concrete. Markdown. No preamble.

FINDINGS:
${JSON.stringify(confirmed, null, 2)}`,
  { label: 'synthesize', phase: 'Synthesize', effort: 'high' },
)

return { confirmed, report: synthesis }

